new="""export interface BudgetVersionsResponse {
  readonly envelopeId: string;
  /** Most recent first (by effectiveFrom descending). */
  readonly versions: readonly BudgetVersionView[];
}

/**
 * Edit ONE budget version in place (Phase 3): amount and/or window. Window
 * changes that touch the neighbours come back as a 409 "neighbour_adjustments"
 * carrying the suggested updates ("update the previous budget's end date so
 * they continue to line up") unless the request states a decision:
 * acceptAdjustments true applies required AND optional suggestions; false
 * applies only the REQUIRED ones (overlaps are never permitted — doctrine D1;
 * gaps are legal and stay if declined).
