/**
 * Budget-history reconstruction (owner request 2026-08-12: "there are a number
 * of other budgets before [1/1/25] that you have missed").
 *
 * PocketSmith's trend analysis yields a category's BUDGETED amount per month
 * (forecast_amount — the sum of its budget events). These pure helpers turn
 * that monthly series into non-overlapping budget ERAS (consecutive months
 * with the same amount collapse into one window) and merge them UNDER an
 * existing BudgetBuddy chronology:
 *
 *   - Eras are imported only for history BEFORE the takeover date (the
 *     envelope's BudgetBuddy anchor, capped by its earliest hand-authored
 *     version) — BudgetBuddy-authored budgets are never touched.
 *   - When the era immediately before the takeover has the SAME amount as the
 *     takeover-era budget, the existing line is extended BACK to the era's
 *     start instead of minting a duplicate ("current budget since 1/1/25").
 *   - Zero-budget months become GAPS (no line), which the model treats as
 *     no-budget legally.
 */

import type { BudgetTemplate } from "../domain/types.ts";
import { previousDay } from "../budget/versions.ts";

export interface MonthBudget {
  /** First day of the month, YYYY-MM-DD. */
  readonly month: string;
  readonly amountCents: number;
}

export interface BudgetEra {
  /** First day of the era's first month. */
  readonly from: string;
  /** Last day of the era's final month. */
  readonly to: string;
  readonly amountCents: number;
}

/** Last day of the month containing the given first-day date. */
export function lastDayOfMonth(firstDay: string): string {
  const y = Number(firstDay.slice(0, 4));
  const m = Number(firstDay.slice(5, 7));
  const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
  return `${firstDay.slice(0, 8)}${String(last).padStart(2, "0")}`;
}

/** Collapse a monthly budget series into eras; zero months become gaps. */
export function erasFromMonthly(series: readonly MonthBudget[]): BudgetEra[] {
  const sorted = [...series].sort((a, b) => a.month.localeCompare(b.month));
  const eras: BudgetEra[] = [];
  for (const p of sorted) {
    if (p.amountCents === 0) continue; // gap: no budget that month
    const last = eras[eras.length - 1];
    const contiguous =
      last !== undefined &&
      last.amountCents === p.amountCents &&
      previousDay(p.month) === last.to;
    if (contiguous) {
      eras[eras.length - 1] = { ...last!, to: lastDayOfMonth(p.month) };
    } else {
      eras.push({ from: p.month, to: lastDayOfMonth(p.month), amountCents: p.amountCents });
    }
  }
  return eras;
}

export interface MergePlan {
  /** New lines to insert (uuid assignment is the caller's job — id left ""). */
  readonly inserts: readonly Omit<BudgetTemplate, "id" | "userId">[];
  /** The takeover line extended back (same amount adjacency), when applicable. */
  readonly extendTakeoverTo: string | null;
  /** Human-readable era table for the report. */
  readonly report: readonly string[];
}

/**
 * Plan the merge of historical eras UNDER the takeover line. `takeoverFrom` is
 * the first day the existing BudgetBuddy budget owns; `takeoverAmountCents` its
 * amount. Eras are clipped to end before takeoverFrom.
 */
export function planHistoryMerge(
  envelopeId: string,
  eras: readonly BudgetEra[],
  takeoverFrom: string,
  takeoverAmountCents: number,
): MergePlan {
  const clipped: BudgetEra[] = [];
  for (const e of eras) {
    if (e.from >= takeoverFrom) continue; // inside BudgetBuddy-owned history
    clipped.push(e.to >= takeoverFrom ? { ...e, to: previousDay(takeoverFrom) } : e);
  }
  const report: string[] = [];
  let extendTakeoverTo: string | null = null;
  const inserts: Omit<BudgetTemplate, "id" | "userId">[] = [];
  for (const e of clipped) {
    const adjoinsTakeover = previousDay(takeoverFrom) === e.to;
    if (adjoinsTakeover && e.amountCents === takeoverAmountCents) {
      // Same amount right up to the takeover: one continuous budget.
      extendTakeoverTo = e.from;
      report.push(`  ${e.from} .. (continues as current) ${(e.amountCents / 100).toFixed(2)}/mo — extends current budget back`);
      continue;
    }
    inserts.push({
      envelopeId,
      amountCents: e.amountCents,
      period: "monthly",
      effectiveFrom: e.from,
      effectiveTo: e.to,
    });
    report.push(`  ${e.from} .. ${e.to}  ${(e.amountCents / 100).toFixed(2)}/mo`);
  }
  return { inserts, extendTakeoverTo, report };
}

/**
 * One-off budget-history backfill from PocketSmith (owner request 2026-08-12).
 *
 *   bun run scripts/backfill-budget-history.ts            # dry-run (report only)
 *   bun run scripts/backfill-budget-history.ts --apply    # write (after a DB backup)
 *
 * For every mapped category, pulls the REAL monthly budget series from
 * PocketSmith trend analysis (forecast_amount = its budget events), collapses
 * it into eras, and imports the eras UNDER the existing BudgetBuddy chronology:
 * history before the envelope's takeover (its anchor date, capped by its
 * earliest hand-authored version) is filled; BudgetBuddy-authored budgets are
 * never modified — except extending the takeover line BACK when the adjacent
 * era carries the same amount ("current budget since 1/1/25"). Historical
 * materialised months are then recomputed from the final chronology (D4).
 */

import { copyFileSync, existsSync } from "node:fs";
import { buildContainer } from "../src/composition.ts";
import { installSecretLogRedaction } from "../src/server/redaction.ts";
import { PocketSmithClient } from "../src/ingest/client.ts";
import { erasFromMonthly, planHistoryMerge, type MonthBudget } from "../src/ingest/budget-history.ts";
import { effectiveFromOf, effectiveToOf, resolveTemplateForMonth } from "../src/budget/versions.ts";
import { findOverlaps, isTombstone } from "../src/budget/window.ts";
import type { BudgetTemplate } from "../src/domain/types.ts";
import type { EnvelopeStore } from "../src/envelope/ports.ts";
import type { BudgetStore } from "../src/budget/ports.ts";

const APPLY = process.argv.includes("--apply");
const userId = process.env.PENNY_USER_ID ?? "local";
const DEFAULT_TAKEOVER = "2026-06-01"; // the BudgetBuddy import month

const container = await buildContainer();
const { secrets } = installSecretLogRedaction(container.secrets);
const store = container.store as BudgetStore & EnvelopeStore;

if (APPLY) {
  const dbPath = process.env.PENNY_SQLITE_PATH ?? `${process.env.HOME}/.penny/penny.db`;
  if (existsSync(dbPath)) {
    const backup = dbPath.replace(/\.db$/, `.pre-history-backfill.db`);
    copyFileSync(dbPath, backup);
    if (existsSync(`${dbPath}-wal`)) copyFileSync(`${dbPath}-wal`, `${backup}-wal`);
    console.log(`[backfill] backup written: ${backup}`);
  }
}

const client = await PocketSmithClient.forUser(secrets, userId);
const user = await client.getAuthenticatedUser();
if (user.id === undefined || user.id === null) throw new Error("PocketSmith returned no user id.");

// Scenario ids (trend analysis requires them) from the accounts surface.
const accounts = await client.listAccounts(user.id);
const scenarioIds = [
  ...new Set(
    accounts.flatMap((a) => [
      ...(a.scenarios?.map((sc) => sc.id) ?? []),
      a.primary_scenario?.id,
    ]).filter((x): x is number => typeof x === "number"),
  ),
];
if (scenarioIds.length === 0) throw new Error("No PocketSmith scenarios found.");

const [mappings, template, incomes, txs] = await Promise.all([
  store.listMappings(userId),
  store.listTemplate(userId),
  store.listIncomeEnvelopes(userId),
  store.listTransactions(userId),
]);
const incomeIds = new Set(incomes.map((i) => i.id));
const catToEnv = new Map(mappings.map((m) => [m.categoryId, m.envelopeId]));
const categoryIds = [...catToEnv.keys()];

const firstTxMonth = txs.reduce<string | null>((min, t) => (min === null || t.date < min ? t.date : min), null)?.slice(0, 7);
if (!firstTxMonth) throw new Error("No transactions — nothing to backfill against.");
const startDate = `${firstTxMonth}-01`;
const endDate = new Date().toISOString().slice(0, 10);

console.log(`[backfill] trend analysis ${startDate}..${endDate} for ${categoryIds.length} categories, scenarios [${scenarioIds.join(",")}]`);
const packages = await client.trendAnalysis(user.id, { categories: categoryIds, scenarios: scenarioIds, startDate, endDate });

const toCents = (amount: number | undefined): number =>
  amount === undefined || Number.isNaN(amount) ? 0 : Math.abs(Math.round(amount * 100));

let insertedTotal = 0;
let extendedTotal = 0;
for (const pkg of packages) {
  const catId = pkg.category?.id;
  if (catId === undefined) continue;
  const envelopeId = catToEnv.get(String(catId));
  if (envelopeId === undefined) continue;
  const isIncome = incomeIds.has(envelopeId);
  const analysis = isIncome ? pkg.income : pkg.expense;
  const periods = analysis?.periods ?? [];
  const series: MonthBudget[] = periods
    .filter((p) => p.start_date !== undefined)
    .map((p) => ({ month: p.start_date!, amountCents: toCents(p.forecast_amount) }));
  const eras = erasFromMonthly(series);
  if (eras.length === 0) continue;

  // The takeover: the envelope's earliest live BudgetBuddy line (its start is
  // where BudgetBuddy's own chronology begins), else the import default.
  const live = template.filter((l) => l.envelopeId === envelopeId && !isTombstone(l));
  const earliest = live.sort((a, b) => effectiveFromOf(a).localeCompare(effectiveFromOf(b)))[0];
  // For incomes with no lines yet the whole PS chronology stands alone (the
  // last era stays open-ended by taking over at "9999" and nothing to extend).
  const takeoverFrom = earliest ? effectiveFromOf(earliest) : DEFAULT_TAKEOVER;
  const takeoverAmount = earliest?.amountCents ?? -1;

  const plan = planHistoryMerge(envelopeId, eras, takeoverFrom, takeoverAmount);
  if (plan.inserts.length === 0 && plan.extendTakeoverTo === null) continue;

  const name = pkg.category?.title ?? envelopeId;
  console.log(`\n${name} (${envelopeId})${isIncome ? " [income]" : ""} — takeover ${takeoverFrom}:`);
  for (const line of plan.report) console.log(line);

  if (!APPLY) continue;

  await store.withTransaction(async () => {
    const working: BudgetTemplate[] = (await store.listTemplate(userId)).filter((l) => l.envelopeId === envelopeId);
    for (const ins of plan.inserts) {
      const line: BudgetTemplate = { ...ins, id: crypto.randomUUID(), userId };
      await store.putTemplateLine(userId, line);
      working.push(line);
      insertedTotal++;
    }
    if (plan.extendTakeoverTo !== null && earliest) {
      const extended: BudgetTemplate = {
        ...earliest,
        effectiveFrom: plan.extendTakeoverTo,
        effectiveTo: effectiveToOf(earliest),
      };
      await store.putTemplateLine(userId, extended);
      const idx = working.findIndex((l) => l.id === earliest.id);
      if (idx >= 0) working[idx] = extended;
      extendedTotal++;
    }
    const overlaps = findOverlaps(working.filter((l) => !isTombstone(l)));
    if (overlaps.length > 0) throw new Error(`overlap after merge for ${envelopeId} — aborted`);

    // D4: recompute the envelope's materialised months from the final lines
    // (income envelopes resolve live and materialise nothing).
    if (!isIncome) {
      const months = await store.listAllocationPeriods(userId);
      for (const key of months) {
        if (key < "1990-01" || key > "2100-12") continue;
        const m = { year: Number(key.slice(0, 4)), month: Number(key.slice(5, 7)) };
        const allocs = await store.listAllocations(userId, key);
        if (allocs.length === 0) continue;
        const mine = allocs.find((a) => a.envelopeId === envelopeId);
        if (mine?.scope === "this_month") continue;
        const resolved = resolveTemplateForMonth(working, m).get(envelopeId) ?? 0;
        if ((mine?.amountCents ?? 0) === resolved) continue;
        await store.putAllocation(userId, {
          id: mine?.id ?? crypto.randomUUID(),
          envelopeId,
          period: key,
          amountCents: resolved,
          scope: "ongoing",
        });
      }
    }
  });
}

console.log(`\n[backfill] ${APPLY ? "APPLIED" : "DRY-RUN"}: ${insertedTotal} historical versions inserted, ${extendedTotal} current budgets extended back.`);
await store.close();

