    // current budget reads "from 2025-01-01 — ongoing".
    expect(plan.extendTakeoverTo).toBe("2025-01-01");
    // The earlier 700000 era imports as a closed historical version.
    expect(plan.inserts).toEqual([
      { envelopeId: "inc-salary", amountCents: 700000, period: "monthly", effectiveFrom: "2024-11-01", effectiveTo: "2024-12-31" },
    ]);
  });

