    const eras = erasFromMonthly([{ month: "2026-05-01", amountCents: 111100 }]);
    const plan = planHistoryMerge("env-x", eras, "2026-06-01", 999900);
    expect(plan.extendTakeoverTo).toBeNull();
    expect(plan.inserts[0]).toMatchObject({ effectiveFrom: "2026-05-01", effectiveTo: "2026-05-31", amountCents: 111100 });
  });

